    "query": "host = 'login-portal-verify.example.com' OR host = 'cdn-sync.example.net' OR host = '203.0.113.45'"
  }
}
```

2. DNS logs:
```
{
  "name": "search_logs",
  "arguments": {
    "collection": "dns_logs",
    "query": "query_name = 'login-portal-verify.example.com' OR query_name = 'cdn-sync.example.net' OR query_name = '203.0.113.45'"
  }
}
```

3. EDR logs:
```
{
  "name": "search_logs",
